const body = $json.body ?? $json;
const data = body.data ?? body;
const key = data.key ?? body.key ?? {};
const jid = String(key.remoteJid ?? data.remoteJid ?? body.remoteJid ?? '');
const fromMe = key.fromMe ?? data.fromMe ?? body.fromMe ?? false;
const messageObj = data.message ?? body.message ?? {};
const message = messageObj.conversation
  ?? messageObj.extendedTextMessage?.text
  ?? messageObj.imageMessage?.caption
  ?? messageObj.videoMessage?.caption
  ?? data.text
  ?? body.text
  ?? '';
// Only reply to direct chats with a standard WhatsApp phone JID.
// Ignore groups, status broadcasts, LID-only identifiers and bot's own messages.
if (!jid.endsWith('@s.whatsapp.net') || jid.endsWith('@g.us') || jid === 'status@broadcast' || fromMe || !String(message).trim()) return [];
const number = jid.split('@')[0].split(':')[0].replace(/\D/g, '');
if (!number || number.length < 7) return [];
const lower = String(message).trim().toLowerCase();
const catalog = ['📚 *CATÁLOGO KIAZOP LIVROS*', '', '1. E-books de trading', '2. Finanças e investimentos', '3. Desenvolvimento pessoal', '4. Outros livros digitais', '', 'Responde com o número da categoria e diz a moeda pretendida: *AOA* (kwanza) ou *BRL* (real).', 'Os preços e a disponibilidade serão confirmados pelo atendimento antes do pagamento.'].join('\n');
let reply = 'Olá! 👋 Bem-vindo à KIAZOP Livros.\n\nEscreve *CATÁLOGO* para ver os livros, *MOEDA* para escolher AOA/BRL ou *ATENDIMENTO* para falar com uma pessoa.';
if (lower.includes('catálogo') || lower.includes('catalogo') || lower === 'livro' || lower.includes('livros')) reply = catalog;
else if (lower.includes('moeda') || lower.includes('aoa') || lower.includes('brl') || lower.includes('kwanza') || lower.includes('real')) reply = 'Podes comprar em *AOA (kwanza angolano)* ou *BRL (real brasileiro)*. Diz-me qual preferes e qual e-book procuras. O valor final será confirmado antes do pagamento.';
else if (['1','2','3','4'].includes(lower)) { const categories = {'1':'E-books de trading','2':'Finanças e investimentos','3':'Desenvolvimento pessoal','4':'Outros livros digitais'}; reply = 'Selecionaste: *' + categories[lower] + '*.\nIndica o título que procuras e a moeda (AOA ou BRL). Envia *CATÁLOGO* para voltar às categorias.'; }
else if (lower.includes('atendimento') || lower.includes('humano') || lower.includes('ajuda') || lower.includes('atendente')) reply = 'Claro! Um responsável irá ajudar-te. Envia o título do livro e a moeda pretendida (AOA ou BRL).';
else if (lower.includes('paguei') || lower.includes('pagamento') || lower.includes('comprovativo')) reply = 'Obrigado! A entrega só será confirmada depois de verificarmos o pagamento no sistema do vendedor. Envia o número do pedido ao atendimento. Não envies dados de cartão ou palavras-passe.';
return [{ json: { remoteJid: number, reply } }];
